    id: randomUUID(),
    title,
    author,
    notes: (input.notes || "").trim(),
    finished: false,
    createdAt: Date.now(),
  };
}

/** @param {Book[]} books @param {string} id */
export function findBook(books, id) {
  return books.find((b) => b.id === id) || null;
}

/** @param {Book[]} books @param {string} id @param {Partial<Book>} patch */
export async function updateBook(books, id, patch) {
  const book = findBook(books, id);
  if (!book) return null;
  if (typeof patch.notes === "string") book.notes = patch.notes;
  if (typeof patch.finished === "boolean") book.finished = patch.finished;
  await saveBooks(books);
  return book;
}

// ---------------------------------------------------------------------------
// HTML rendering (tiny, dependency-free)
// ---------------------------------------------------------------------------

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

