    h1, h2 { margin-top: 2rem; }
    h1 a { text-decoration: none; color: inherit; }
    .book { padding: .75rem 0; border-bottom: 1px solid #eee; }
    .book .title { font-weight: 600; }
    .book .author { color: #666; }
    .muted { color: #666; }
    form label { display: block; margin: .75rem 0 .25rem; font-weight: 600; }
    input[type=text], textarea { width: 100%; box-sizing: border-box; padding: .5rem; font: inherit; border: 1px solid #ccc; border-radius: 4px; }
    textarea { min-height: 6rem; resize: vertical; }
    button { padding: .5rem 1rem; font: inherit; cursor: pointer; border: 0; border-radius: 4px; background: #2a5db0; color: #fff; }
    button.secondary { background: #eee; color: #333; }
    .actions { margin-top: 1rem; display: flex; gap: .5rem; flex-wrap: wrap; }
    .empty { color: #999; font-style: italic; }
    .share-url { font-family: ui-monospace, monospace; background: #f4f4f4; padding: .25rem .5rem; border-radius: 4px; }
  </style>
</head>
<body>
${body}
</body>
</html>`;
}

function bookLink(book) {
  return `/books/${book.id}`;
}

/** @param {Book[]} books */
function renderHome(books) {
  const current = books.filter((b) => !b.finished);
  const finished = books.filter((b) => b.finished);

  const renderItem = (b) => `
    <div class="book">
      <div class="title"><a href="${bookLink(b)}">${escapeHtml(b.title)}</a></div>
      <div class="author">by ${escapeHtml(b.author)}</div>
    </div>`;

  const currentHtml = current.length
    ? current.map(renderItem).join("")
    : `<p class="empty">Nothing in progress yet.</p>`;

  const finishedHtml = finished.length
    ? finished.map(renderItem).join("")
    : `<p class="empty">Nothing finished yet.</p>`;

  const body = `
    <h1><a href="/">Reading List</a></h1>
    <p><a href="/books/new">+ Add a book</a></p>

    <h2>Currently reading</h2>
    ${currentHtml}

    <h2>Finished</h2>
    ${finishedHtml}
  `;
  return layout("Reading List", body);
}

function renderNewForm(error = "") {
  const errorHtml = error ? `<p style="color:#b00">${escapeHtml(error)}</p>` : "";
