  const status = book.finished ? "Finished" : "Currently reading";
  const toggleAction = book.finished ? "Mark as reading" : "Mark as finished";
  const toggleValue = book.finished ? "false" : "true";

  const body = `
    <h1><a href="/">Reading List</a></h1>
    <h2>${escapeHtml(book.title)}</h2>
    <p class="muted">by ${escapeHtml(book.author)} &middot; ${escapeHtml(status)}</p>

    <h3>Notes</h3>
    <form method="post" action="/books/${encodeURIComponent(book.id)}/notes">
      <textarea name="notes" placeholder="No notes yet.">${escapeHtml(book.notes)}</textarea>
      <div class="actions">
        <button type="submit">Save notes</button>
      </div>
    </form>

    <form method="post" action="/books/${encodeURIComponent(book.id)}/finished">
      <input type="hidden" name="finished" value="${toggleValue}" />
      <div class="actions">
        <button type="submit">${escapeHtml(toggleAction)}</button>
        <a class="button secondary" href="/">Back to list</a>
      </div>
    </form>

    <h3>Share link</h3>
