 * Request handler. Exported for testing.
 * @param {{method:string,url:string,body?:object}} req
 * @param {{host?:string}} [ctx]
 */
export async function handleRequest(req, ctx = {}) {
  const method = req.method.toUpperCase();
  const path = routePath(req.url);
  const host = ctx.host || "localhost:3000";
  const books = await loadBooks();

  // Home
  if (method === "GET" && path === "/") {
    return { status: 200, body: renderHome(books) };
  }

  // New book form
  if (method === "GET" && path === "/books/new") {
    return { status: 200, body: renderNewForm() };
  }

  // Create book
  if (method === "POST" && path === "/books") {
    try {
      const book = makeBook(req.body || {});
      books.push(book);
      await saveBooks(books);
      return { status: 303, headers: { Location: `/books/${book.id}` } };
    } catch (err) {
      return { status: 400, body: renderNewForm(err.message) };
    }
  }

  // Book detail
  const detailMatch = method === "GET" && path.match(/^\/books\/([^/]+)$/);
  if (detailMatch) {
    const book = findBook(books, decodeURIComponent(detailMatch[1]));
    if (!book) return { status: 404, body: layout("Not found", "<h1>Book not found</h1>") };
    const shareUrl = `http://${host}/books/${book.id}`;
    return { status: 200, body: renderBook(book, shareUrl) };
  }

  // Update notes
  const notesMatch = method === "POST" && path.match(/^\/books\/([^/]+)\/notes$/);
  if (notesMatch) {
    const id = decodeURIComponent(notesMatch[1]);
    const updated = await updateBook(books, id, { notes: (req.body || {}).notes || "" });
    if (!updated) return { status: 404, body: layout("Not found", "<h1>Book not found</h1>") };
    return { status: 303, headers: { Location: `/books/${id}` } };
  }

  // Toggle finished
  const finishedMatch = method === "POST" && path.match(/^\/books\/([^/]+)\/finished$/);
  if (finishedMatch) {
    const id = decodeURIComponent(finishedMatch[1]);
    const finished = (req.body || {}).finished === "true";
    const updated = await updateBook(books, id, { finished });
    if (!updated) return { status: 404, body: layout("Not found", "<h1>Book not found</h1>") };
    return { status: 303, headers: { Location: `/books/${id}` } };
  }

  return { status: 404, body: layout("Not found", "<h1>Not found</h1>") };
}

// ---------------------------------------------------------------------------
// Bootstrap
// ---------------------------------------------------------------------------

export function startServer(port = PORT) {
  const server = createServer(async (req, res) => {
    try {
      let body = undefined;
      if (req.method === "POST") body = await readBody(req);
      const result = await handleRequest(
        { method: req.method, url: req.url, body },
        { host: req.headers.host || `localhost:${port}` }
      );
      if (result.status >= 300 && result.status < 400 && result.headers?.Location) {
        return redirect(res, result.headers.Location);
      }
      send(res, result.status, result.body || "");
    } catch (err) {
      console.error(err);
      send(res, 500, layout("Error", `<h1>Something went wrong</h1><pre>${escapeHtml(err.message)}</pre>`));
    }
  });

  return new Promise((resolve) => {
    server.listen(port, () => {
      console.log(`Reading list app running at http://localhost:${port}`);
      resolve(server);
    });
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  startServer();
}
"}

